import { revalidateTag } from 'next/cache';
import { getAllProducts } from '@/lib/db';

// Child component that fetches and caches product data
async function ProductList() {
  'use cache';

  // Apply cache tag for selective invalidation
  const cacheTag = 'products';

  const products = await getAllProducts();

  return (
    <div style={{ marginBottom: '2rem' }}>
      <h2>Product Catalog</h2>
      <p style={{ fontSize: '0.875rem', color: '#666' }}>
        Cached at: {new Date().toISOString()}
      </p>
      <ul style={{ listStyle: 'none', padding: 0 }}>
        {products.map((product) => (
          <li
            key={product.id}
            style={{
              padding: '1rem',
              marginBottom: '0.5rem',
              border: '1px solid #ddd',
              borderRadius: '4px'
            }}
          >
            <strong>{product.name}</strong> - ${product.price}
          </li>
        ))}
      </ul>
    </div>
  );
}

// Configure cache with tags for the ProductList component
ProductList.cache = {
  tags: ['products']
};

export default function Page() {
  // Server action to invalidate the products cache
  async function refreshProducts() {
    'use server';
    revalidateTag('products');
  }

  return (
    <div style={{ padding: '2rem', maxWidth: '600px', margin: '0 auto' }}>
      <h1>Product Listing with Cache Invalidation</h1>

      {/* Cached product list component */}
      <ProductList />

      {/* Form with inline server action for cache invalidation */}
      <form action={refreshProducts}>
        <button
          type="submit"
          style={{
            padding: '0.75rem 1.5rem',
            backgroundColor: '#0070f3',
            color: 'white',
            border: 'none',
            borderRadius: '4px',
            cursor: 'pointer',
            fontSize: '1rem'
          }}
        >
          Refresh Products
        </button>
      </form>

      <div style={{ marginTop: '2rem', padding: '1rem', backgroundColor: '#f5f5f5', borderRadius: '4px' }}>
        <h3 style={{ marginTop: 0 }}>Cache Invalidation Pattern</h3>
        <ul style={{ fontSize: '0.875rem', lineHeight: '1.6' }}>
          <li>ProductList component uses 'use cache' directive for automatic caching</li>
          <li>Cache is tagged with "products" for selective invalidation</li>
          <li>Clicking "Refresh Products" triggers revalidateTag('products')</li>
          <li>Only the products cache is invalidated, not other cached data</li>
          <li>Timestamp shows when data was last fetched and cached</li>
        </ul>
      </div>
    </div>
  );
}

